// workspace checks (offline mode): personal + assigned tasks, done with a closing note, visibility by role
const {chromium}=require('playwright');const path=require('path');
const ok=(c,m)=>{console.log((c?'PASS ':'FAIL ')+m);if(!c)process.exitCode=1};
(async()=>{const app=path.resolve(process.argv[2]);const b=await chromium.launch();const p=await b.newPage({viewport:{width:1366,height:900}});const errs=[];p.on('pageerror',e=>errs.push(e.message));
const w=ms=>p.waitForTimeout(ms);const as=async u=>{await p.evaluate(u=>{ME=S.users.find(x=>x.user===u);permBump();rerender()},u);await w(200)};
await p.goto('file://'+app+'#/');await p.waitForFunction(()=>window.__KS_OK,{timeout:30000});
await as('admin');await p.goto('file://'+app+'#/admin/work');await w(400);
await p.selectOption('#wqas',{label:'کارشناس تأمین ۱'});await p.fill('#wqadd','شمارش پیچ‌های M12 انبار');await p.press('#wqadd','Enter');await w(400);
const t=await p.evaluate(()=>S.work.tasks[0]);ok(t.title==='شمارش پیچ‌های M12 انبار'&&t.as.join()==='5'&&t.by===1,'admin assigned a task to the supply user ('+t.id+')');
ok(await p.evaluate(()=>S.audit.some(a=>a.act==='ارجاع تسک')),'assignment written to the audit trail');
await p.fill('#wqadd','کار شخصی مدیر');await p.press('#wqadd','Enter');await w(300);
await p.evaluate(()=>{S.work.tasks[0].priv=true});
await as('warehouse');await p.goto('file://'+app+'#/admin/work');await w(400);
ok(await p.isVisible('text=شمارش پیچ‌های M12 انبار')&&!(await p.$('#wqas')),'supply user sees the task assigned to them; cannot assign to others');
ok(!(await p.isVisible('text=همهٔ تسک‌ها'))&&await p.evaluate(()=>!wSee(S.work.tasks.find(t=>t.title==='کار شخصی مدیر'))),'supply user cannot see everyone\'s tasks');
await p.click(`[data-done="${t.id}"]`);await w(300);await p.fill('#wask','۴۰ جعبه شمارش شد');await p.click('#wok');await w(400);
const t2=await p.evaluate(id=>S.work.tasks.find(x=>x.id===id),t.id);ok(t2.status==='done'&&t2.cm.some(c=>c.kind==='done'&&c.text==='۴۰ جعبه شمارش شد'),'marked done with a closing note');
await p.goto('file://'+app+'#/admin/work?t='+t.id);await w(500);ok((await p.textContent('.w-cms')).includes('گزارش انجام'),'closing note shown in «اقدامات و توضیحات»');
await p.fill('#wt_cm','برچسب قفسه‌ها هم عوض شد');await p.click('#wt_cmadd');await w(200);ok(await p.evaluate(id=>S.work.tasks.find(x=>x.id===id).cm.length===2,t.id),'comment added');
await p.keyboard.press('Escape');await w(200);
await as('sales');ok(await p.evaluate(()=>can('work.task.view_all')&&can('work.task.assign')),'sales manager can assign and see all');
ok(await p.evaluate(()=>!wSee(S.work.tasks.find(t=>t.title==='کار شخصی مدیر'))),'private task hidden even from «see all»');
await p.goto('file://'+app+'#/admin/work?v=board&f=all');await w(400);
ok(await p.evaluate(()=>document.querySelectorAll('.w-col').length===S.work.cfg.statuses.length),'board has one column per status');
await as('admin');await p.goto('file://'+app+'#/admin/work?v=settings');await w(400);await p.click('[data-add="statuses"]');await w(300);
ok(await p.evaluate(()=>S.work.cfg.statuses.length===6),'admin added a status in settings');
await as('admin');await p.goto('file://'+app+'#/admin/home');await w(400);ok((await p.textContent('#app')).includes('تسک‌های باز من'),'home shows «تسک‌های باز من»');
ok(await p.evaluate(()=>roleOf('warehouse').perms.includes('work.task.create')&&!roleOf('warehouse').perms.includes('work.task.assign')),'role permissions for the workspace');
ok(!errs.length,'no JS errors '+errs.slice(0,3));await b.close()})();
